// P returns a pointer to the input value, including when the input is the zero value of its type.
func P[T any](v T) *T {
	return &v
}

// V returns the value referenced by p, or the zero value of the type when p is nil.
func V[T any](p *T) T {
	var zero T
	if p == nil {
		return zero
	}
	return *p
}
